/** A message's key; `….one` keys are the singular forms `translate` picks for a count of one. */
type AnyKey = keyof typeof en;
export type MessageKey = Exclude<AnyKey, `${string}.one`>;
type SingularKey = Extract<AnyKey, `${string}.one`>;

